     if (r,c) in idx: bystart[idx[(r,c)]].append((ti,b,(r,c,h,w),name))
 # counts tuple
 init=tuple(n for _,n,_ in dims)
 @lru_cache(None)
 def rec(occ, rem):
  # return up to limit tilings suffix (list of (placements))
